## Architecture Patterns

### Recommended Project Structure
```
apps/server/src/
├── db/
│   └── schema.ts           # Add creditBalance, transactions tables
├── lib/
│   └── credits.ts          # Credit service: deduct, checkBalance, getHistory
└── routes/
    └── credits.ts          # API endpoints: GET /balance, GET /history
```

### Pattern 1: Immutable Transaction Ledger
**What:** Append-only table recording every credit change as a separate row.
**When to use:** All credit systems - provides full audit trail and source of truth.
**Example:**
```typescript
// Source: Research synthesis from transaction ledger best practices
export const transactions = pgTable('transactions', {
  id: text('id').primaryKey().$defaultFn(() => crypto.randomUUID()),
  userId: text('user_id').notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  amount: integer('amount').notNull(), // Positive for credits added, negative for deductions
  type: text('type').notNull(), // 'signup_bonus' | 'chapter_read'
  description: text('description').notNull(),

  // Metadata for "chapter_read" transactions
  mangaTitle: text('manga_title'),
  chapterNumber: text('chapter_number'),
  platform: text('platform'), // 'webtoon' | 'tapas' | 'mangadex'
  sourceUrl: text('source_url'),
  cached: boolean('cached'), // true if cached chapter (2 credits), false if new (4 credits)

  createdAt: timestamp('created_at').defaultNow().notNull(),
});
```

### Pattern 2: Cached Balance with Transaction Source of Truth
**What:** Store current balance in users table, update atomically with each transaction.
**When to use:** When balance is read frequently - avoids expensive SUM() queries.
**Example:**
```typescript
// Source: https://orm.drizzle.team/docs/update + performance research
// Add to user table in schema.ts
export const user = pgTable('user', {
  // ... existing fields
  creditBalance: integer('credit_balance').notNull().default(0),
});

// Credit service function
async function deductCredits(
  userId: string,
  amount: number,
  metadata: { type: string; description: string; /* ... */ }
) {
  return await db.transaction(async (tx) => {
    // 1. Create transaction record
    await tx.insert(transactions).values({
      userId,
      amount: -amount, // Negative for deduction
      ...metadata,
    });

    // 2. Update balance atomically and verify
    const [result] = await tx
      .update(user)
      .set({ creditBalance: sql`${user.creditBalance} - ${amount}` })
      .where(eq(user.id, userId))
      .returning({ newBalance: user.creditBalance });

    // 3. Check for insufficient funds
    if (result.newBalance < 0) {
      tx.rollback();
      throw new Error('Insufficient credits');
    }

    return result.newBalance;
  });
}
```

### Pattern 3: Pre-Check Balance Before Operation
**What:** Check balance before starting expensive operation (extraction), refuse if insufficient.
**When to use:** Operations that can't be rolled back once started (external API calls).
**Example:**
```typescript
// Source: PostgreSQL transaction best practices
async function dubChapter(userId: string, chapterId: string, cost: number) {
  // 1. Pre-check balance (cheap query)
  const [userBalance] = await db
    .select({ balance: user.creditBalance })
    .from(user)
    .where(eq(user.id, userId));

  if (userBalance.balance < cost) {
    throw new Error(`Insufficient credits. Need ${cost}, have ${userBalance.balance}`);
  }

  // 2. Perform extraction (expensive, not in transaction)
  const extractedData = await extractChapterText(chapterId);

  // 3. Deduct credits only after success
  await deductCredits(userId, cost, {
    type: 'chapter_read',
    description: `Chapter ${chapterId} dubbing`,
    // ... metadata
  });

  return extractedData;
}
```

### Pattern 4: Offset Pagination for Transaction History
**What:** Use LIMIT/OFFSET with ORDER BY timestamp DESC for paginated history.
**When to use:** Transaction history with page numbers (not infinite scroll).
**Example:**
```typescript
// Source: https://orm.drizzle.team/docs/guides/limit-offset-pagination
import { desc } from 'drizzle-orm';

function withPagination<T extends PgSelect>(
  qb: T,
  page: number = 1,
  pageSize: number = 25,
) {
  return qb.limit(pageSize).offset((page - 1) * pageSize);
}

async function getTransactionHistory(userId: string, page: number = 1) {
  const query = db
    .select()
    .from(transactions)
    .where(eq(transactions.userId, userId))
    .orderBy(desc(transactions.createdAt)); // Critical: order by unique timestamp

  return await withPagination(query.$dynamic(), page, 25);
}
```

### Pattern 5: Signup Bonus in Application Code
**What:** Award starter credits during user creation flow, not via database trigger.
**When to use:** One-time operations that need business logic (e.g., only award if signup source is email/Discord).
**Example:**
```typescript
// Source: Database trigger vs application code best practices
// In Better Auth databaseHooks (apps/server/src/lib/auth.ts)
async function onUserCreate(user: User) {
  // Award signup bonus
  await db.insert(transactions).values({
    userId: user.id,
    amount: 50, // Positive for credit addition
    type: 'signup_bonus',
    description: 'Welcome to Bubbdub! 50 free starter credits',
  });

  // Update balance
  await db
    .update(user)
    .set({ creditBalance: 50 })
    .where(eq(user.id, user.id));
}
```

### Anti-Patterns to Avoid
- **Read-Modify-Write cycles:** Never SELECT balance, calculate in app, UPDATE with new value - use `balance = balance - amount` in SQL
- **Updating transaction records:** Ledger must be append-only; never UPDATE or DELETE transactions
- **Database triggers for signup bonus:** Harder to test, debug, and maintain than application code
- **FLOAT/REAL for credits:** Floating-point errors cause rounding issues; use INTEGER only
- **Missing ORDER BY in pagination:** Results become non-deterministic without ordering by unique column

## Don't Hand-Roll

Problems that look simple but have existing solutions:

| Problem | Don't Build | Use Instead | Why |
|---------|-------------|-------------|-----|
| Race conditions in balance updates | Application-level locking | PostgreSQL transactions + atomic UPDATE | Database handles concurrent updates correctly; app-level locks don't scale |
| Transaction ID generation | Custom counter/timestamp | crypto.randomUUID() | UUIDs are globally unique, cryptographically random, built-in |
| Pagination helper | Manual offset calculation | Drizzle withPagination pattern | Type-safe, reusable, handles edge cases |
| Balance computation | Manual SUM loop in JS | sql`SUM(amount)` aggregate | Database does summation 100x faster than application |

**Key insight:** Credit systems have well-worn paths for concurrency and consistency. Use database transactions, not application-level locks or checks.

## Common Pitfalls

### Pitfall 1: Race Conditions from Read-Modify-Write
**What goes wrong:** Two simultaneous requests read balance=10, both calculate 10-4=6, both write 6. User got 8 credits deducted but balance only decreased by 4.
**Why it happens:** Reading and writing in separate operations creates a window for concurrent modification.
**How to avoid:** Always use `UPDATE balance = balance - amount` pattern within database transaction. Database serializes these operations correctly.
**Warning signs:** Seeing `SELECT balance`, then `UPDATE SET balance = X` in separate statements.

**Source:** [Hacking Banks With Race Conditions](https://medium.com/swlh/hacking-banks-with-race-conditions-2f8d55b45a4b), [PostgreSQL Anti-patterns: Read-Modify-Write Cycles](https://www.enterprisedb.com/blog/postgresql-anti-patterns-read-modify-write-cycles)

### Pitfall 2: Using NUMERIC When INTEGER Suffices
**What goes wrong:** Queries are 10-100x slower because numeric uses multi-precision software arithmetic instead of native CPU operations.
**Why it happens:** Developers assume "credits might be fractional someday" or think numeric is safer for all numbers.
**How to avoid:** Use integer for whole-number credits. Only use numeric if you genuinely need decimal places (e.g., 1.5 credits).
**Warning signs:** `numeric(10,2)` for a points/credits column that never has decimal values.

**Source:** [PostgreSQL int4 vs. float4 vs. numeric](https://www.cybertec-postgresql.com/en/postgresql-int4-vs-float4-vs-numeric/), [PostgreSQL Documentation: Numeric Types](https://www.postgresql.org/docs/current/datatype-numeric.html)

### Pitfall 3: Insufficient Balance Check After Deduction
**What goes wrong:** User starts with 3 credits, tries to deduct 4, balance becomes -1. Transaction commits, user has negative balance.
**Why it happens:** Forgetting to check RETURNING balance value and rollback if negative.
**How to avoid:** Always check returned balance in transaction, call tx.rollback() if negative.
**Warning signs:** UPDATE with RETURNING but no validation of returned value.

**Source:** [PostgreSQL Transactions Tutorial](https://www.postgresql.org/docs/current/tutorial-transactions.html)

### Pitfall 4: Poor Pagination Performance at High Offsets
**What goes wrong:** Page 1000 of transaction history takes 10 seconds because database scans 25,000 rows to skip them.
**Why it happens:** OFFSET requires scanning all skipped rows; performance degrades linearly with offset size.
**How to avoid:** For this phase, use offset pagination (simple, works for 90-day retention). If performance becomes an issue, migrate to cursor pagination in future phase.
**Warning signs:** Queries get slower as page number increases; EXPLAIN shows large "rows removed by offset" count.

**Source:** [Keyset Cursors, Not Offsets, for Postgres Pagination](https://blog.sequinstream.com/keyset-cursors-not-offsets-for-postgres-pagination/), [Understanding Cursor Pagination](https://www.milanjovanovic.tech/blog/understanding-cursor-pagination-and-why-its-so-fast-deep-dive)

### Pitfall 5: Database Triggers for Business Logic
**What goes wrong:** Signup bonus trigger silently fails, hard to debug, tests don't cover it, team doesn't know it exists.
**Why it happens:** Triggers feel "automatic" and keep logic close to data.
**How to avoid:** Use application code for business logic (signup bonuses, notifications). Reserve triggers only for data integrity rules that must be enforced at database level.
**Warning signs:** "Why did this user get 50 credits?" requires reading database schema instead of application code.

**Source:** [Database Triggers vs. Application-Level Handling](https://medium.com/@kavindaheshan96/should-you-use-database-triggers-or-handle-logic-in-your-app-heres-when-and-why-acdc35cf483d), [PostgreSQL Triggers in 2026](https://thelinuxcode.com/postgresql-triggers-in-2026-design-performance-and-production-reality/)

### Pitfall 6: Missing Index on userId in Transactions Table
**What goes wrong:** `SELECT * FROM transactions WHERE user_id = X ORDER BY created_at DESC LIMIT 25` does full table scan.
**Why it happens:** Foreign key doesn't automatically create an index (only enforces constraint).
**How to avoid:** Create compound index on (user_id, created_at DESC) for optimal query performance.
**Warning signs:** Transaction history queries slow down as transaction table grows; EXPLAIN shows sequential scan.

**Source:** [PostgreSQL Indexes and ORDER BY](https://www.postgresql.org/docs/current/indexes-ordering.html), [Descending Indexes in PostgreSQL](https://atlasgo.io/guides/postgres/descending-indexes)

## Code Examples

Verified patterns from official sources:

### Drizzle Transaction with Rollback
```typescript
// Source: https://orm.drizzle.team/docs/transactions
import { eq, sql } from 'drizzle-orm';

async function deductCreditsForChapter(
  userId: string,
  cost: number,
  metadata: ChapterMetadata
): Promise<number> {
  return await db.transaction(async (tx) => {
    // Record transaction
    await tx.insert(transactions).values({
      userId,
      amount: -cost,
      type: 'chapter_read',
      description: `Read ${metadata.mangaTitle} Ch.${metadata.chapterNumber}`,
      mangaTitle: metadata.mangaTitle,
      chapterNumber: metadata.chapterNumber,
      platform: metadata.platform,
      sourceUrl: metadata.sourceUrl,
      cached: metadata.cached,
    });

    // Atomically update and check balance
    const [result] = await tx
      .update(user)
      .set({ creditBalance: sql`${user.creditBalance} - ${cost}` })
      .where(eq(user.id, userId))
      .returning({ newBalance: user.creditBalance });

    if (!result || result.newBalance < 0) {
      tx.rollback(); // Explicit rollback
      throw new Error(`Insufficient credits. Cost: ${cost}, Balance: ${result?.newBalance ?? 0}`);
    }

    return result.newBalance;
  });
}
```

### Aggregate Balance Calculation (Verification)
```typescript
// Source: https://orm.drizzle.team/docs/select
import { sum } from 'drizzle-orm';

async function verifyUserBalance(userId: string): Promise<{ stored: number; computed: number; match: boolean }> {
  // Get stored balance
  const [userRecord] = await db
    .select({ balance: user.creditBalance })
    .from(user)
    .where(eq(user.id, userId));

  // Compute balance from transaction sum
  const [sumResult] = await db
    .select({ total: sum(transactions.amount) })
    .from(transactions)
    .where(eq(transactions.userId, userId));

  const computed = Number(sumResult.total) || 0;
  const stored = userRecord.balance;

  return {
    stored,
    computed,
    match: stored === computed,
  };
}
```

